void add_vectors(
    double *restrict result, 
    const double *restrict input1, 
    const double *restrict input2, 
    int N) 
{
    // Restrict guarantees result, input1, and input2
    // point to distinct, non-overlapping memory regions.
    // Enables aggressive optimization/vectorization.

    for (int i = 0; i < N; i++) {
        result[i] = input1[i] + input2[i];
    }
}

